<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class VerificationReview extends Model { public $timestamps=false; protected $primaryKey='review_id'; protected $fillable=['partner_id','reviewed_by','decision','remarks']; public function partner(){return $this->belongsTo(PartnerProfile::class,'partner_id');} public function reviewer(){return $this->belongsTo(User::class,'reviewed_by');} }
